import { test, expect } from '@playwright/test';

test.describe('Sauce Demo Store - Mobile Responsiveness', () => {
  test('should display the inventory page on mobile viewport', async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
    await page.fill('#user_name', 'standard_user');
    await page.fill('#password', 'secret_sauce');
    await page.click('#react-burger-menu-btn');
    await expect(page).toHaveURL(/.*saucedemo.com/);
    await expect(page.locator('#logout_sidebar_link')).toBeVisible();
  });

  test('should not change URL when clicking the burger menu button on mobile viewport', async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
    await page.fill('#user_name', 'standard_user');
    await page.fill('#password', 'secret_sauce');
    await page.click('#react-burger-menu-btn');
    await expect(page).toHaveURL(/.*saucedemo.com/);
    await expect(page.locator('#logout_sidebar_link')).toBeVisible();
  });
});
